40	/* One bucket per audit action, so the feed reads as icons rather than dots. */
41	function actIcon(action: string): { icon: string; tone: "" | "c" | "v" | "m" } {
42	  if (action.startsWith("wallet") || action.includes("invoice") || action.includes("topup")) return { icon: "card", tone: "m" };
43	  if (action.includes("create") || action.includes("provision")) return { icon: "cloudup", tone: "c" };
44	  if (action.includes("restore") || action.includes("snapshot") || action.includes("backup")) return { icon: "refresh", tone: "" };
45	  if (action.startsWith("domain")) return { icon: "nodes", tone: "c" };
46	  if (action.includes("delete") || action.includes("suspend")) return { icon: "warntriangle", tone: "m" };
47	  if (action.includes("build") || action.includes("matrix")) return { icon: "terminal", tone: "v" };
48	  return { icon: "activity", tone: "v" };
49	}
