51	function nxStatus(status: string): Row["status"] {
52	  if (status === "RUNNING") return "Online";
53	  if (["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(status)) return "Maintenance";
54	  return "Offline";
55	}
