57	/* "Jan 12, 2026" + "in 45 days", the two lines the Renewal column shows. */
58	function renewal(expiresAt: Date | null): { renew: string; inDays: string } {
59	  if (!expiresAt) return { renew: "—", inDays: "no term" };
60	  const days = Math.round((expiresAt.getTime() - Date.now()) / 86_400_000);
61	  return {
62	    renew: expiresAt.toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" }),
63	    inDays: days < 0 ? `${-days} days ago` : days === 0 ? "today" : `in ${days} day${days === 1 ? "" : "s"}`,
64	  };
65	}
66	
67	function ago(d: Date): string {
68	  const m = Math.floor((Date.now() - d.getTime()) / 60_000);
69	  if (m < 1) return "just now";
70	  if (m < 60) return `${m} min ago`;
71	  const h = Math.floor(m / 60);
72	  if (h < 24) return `${h} hour${h === 1 ? "" : "s"} ago`;
73	  const dd = Math.floor(h / 24);
74	  return dd === 1 ? "Yesterday" : `${dd} days ago`;
75	}
