77	export default async function DashboardPage() {
78	  const user = await requireUser();
79	  const monthAgo = new Date(Date.now() - 30 * 86_400_000);
80	
81	  const [servers, hostingCount, hasFree, auditLogs, openTickets, newThisMonth, plans, gamePlans, hostingPlans, emailPlans] =
82	    await Promise.all([
83	      db.server.findMany({
84	        where: { userId: user.id },
85	        // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs; `node`
86	        // carries the region the Location column shows.
87	        // `portForwards` joins `dedicatedIp`/`node` as what connectAddress needs
88	        // to work out the address a customer can actually reach the box on.
89	        include: {
90	          plan: true, osTemplate: true, gamePlan: true, dedicatedIp: true, node: true,
91	          portForwards: { select: { publicPort: true, guestPort: true } },
92	        },
93	        orderBy: { createdAt: "desc" },
94	      }),
95	      /* This dashboard's own "Total Services" stat and its widget's per-type
96	         tab counts used to come from `servers.length`/`rows` alone — which
97	         only ever holds VPS + game-server rows (this same `db.server`
98	         query). Shared Hosting and a claimed free server are real services
99	         (lib/nx/services.ts's `listServices()`, which /dashboard/services
100	         correctly uses, counts them) but live in different tables
101	         (HostingAccount, FreeMinecraftServer) this page never queried, so
102	         they silently read as 0 here — the exact "undercounts your own
103	         services" bug audited today. Two cheap counts, not a full re-fetch
104	         of listServices()'s richer rows (this page's own `rows` table is
105	         VPS/game-only by design, showing recent server activity — these are
106	         only for getting the STAT AND TAB NUMBERS honest). */
107	      db.hostingAccount.count({ where: { userId: user.id } }),
108	      db.freeMinecraftServer.findUnique({ where: { userId: user.id }, select: { id: true } }),
109	      db.auditLog.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 8 }),
110	      db.ticket.count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }),
111	      db.server.count({ where: { userId: user.id, createdAt: { gte: monthAgo } } }),
112	      db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
113	      db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
114	      db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
115	      /* `active: true` matters here specifically: staging (and, presumably,
116	         any long-lived install) accumulates retired $0 plan rows — this fork
117	         has 5 of them ("Unlimited", a few bundled-hosting-email leftovers,
118	         "Free Domain Inbox") — and a query with no active filter, sorted
119	         priceCents ascending, picks one of those up first. That is the exact
120	         "Business Email $0.00/mo" bug: real Starter is $1.99, not $0. */
121	      db.emailPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
122	    ]);
123	
124	  const uptime = await uptimeFor(servers.map((s) => s.id));
125	  // The play-subdomain base is an admin setting shared by free and paid game
126	  // servers, so the connect address stays right if the owner ever moves it.
127	  const gameBase = await gameSubdomainBase();
128	
129	  /* Was anything removed in the window? If so, last month's estate cannot be
130	     reconstructed from what is still in the table, and any delta computed from
131	     the survivors could only ever point up. Better no delta than a number that
132	     is wrong in one direction by construction. */
133	  const removals = await db.auditLog.count({
134	    where: {
135	      userId: user.id,
136	      createdAt: { gte: monthAgo },
137	      OR: [{ action: { contains: "delete" } }, { action: { contains: "terminate" } }, { action: { contains: "cancel" } }],
138	    },
139	  });
140	
141	  // "Monthly spend" is priced through `renewalCharge` — the single function
142	  // worker/billing.ts, the saved-card path and the "Renew now" button all charge
143	  // through (lib/renewal-charge.ts). Summing `plan.priceCents` instead is a
144	  // SECOND formula and a different number: it bills a $4.99 game server at its
145	  // $8.99 base VPS plan and counts nothing for purchased extra disk or a
146	  // dedicated IP the customer really does pay for every cycle.
147	  const paid = servers.filter((s) => !s.isFree && s.status !== "DELETING");
148	  const spendTaxRatePercent = (await taxContextForUser(user)).ratePercent;
149	  const spendPrices =
150	    paid.length > 0
151	      ? {
152	          ipMonthlyCents: await dedicatedIpMonthlyCents(),
153	          extraDiskPerGbCents: await extraDiskPerGbCents(),
154	          backupPlusCents: await backupPlusMonthlyCents(),
155	          annualDiscountPct: await annualDiscountPct(),
156	          taxRatePercent: spendTaxRatePercent,
157	        }
158	      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent: spendTaxRatePercent };
159	  const monthlySpendCents = paid.reduce((sum, s) => {
160	    const charge = renewalCharge(s, spendPrices);
161	    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
162	  }, 0);
163	
164	  /* Last month's recurring cost, priced the same way through `renewalCharge` —
165	     the estate as it stood 30 days ago is the servers that already existed then.
166	     Only trustworthy when nothing was removed since (see `removals`). */
167	  const priorPaid = paid.filter((s) => s.createdAt < monthAgo);
168	  const priorSpendCents = priorPaid.reduce((sum, s) => {
169	    const charge = renewalCharge(s, spendPrices);
170	    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
171	  }, 0);
172	  const spendDelta =
173	    removals > 0 || priorSpendCents === 0 || priorSpendCents === monthlySpendCents
174	      ? undefined
175	      : {
176	          dir: (monthlySpendCents > priorSpendCents ? "up" : "down") as "up" | "down",
177	          text: `${Math.round((Math.abs(monthlySpendCents - priorSpendCents) / priorSpendCents) * 100)}%`,
178	        };
179	
180	  const transitional = servers.some((s) =>
181	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
182	  );
183	
184	  const KIND = (s: (typeof servers)[number]) =>
185	    s.gamePlan ? "Game Server" : "VPS";
186	
187	  const rows: Row[] = servers.map((s) => {
188	    const kind = KIND(s);
189	    const region = s.node?.region ?? "sgp1";
190	    return {
191	      id: s.id,
192	      name: s.label || s.hostname,
193	      /* Through the one derivation the "your server is ready" email also uses
194	         (lib/nx/connect-address.ts), so the dashboard and that email can never
195	         disagree about where to connect.
196	
197	         This line used to lead with `s.ipAddress`, which is the INTERNAL
198	         10.20.x.x address behind the host's NAT — unreachable from outside and
199	         worse than showing nothing. The comment that was here warned that the
200	         rewritten dashboard has to re-carry main's fixes or the design would
201	         reintroduce them; it did exactly that, and this is the repair. */
202	      addr: connectAddress(s, gameBase).address ?? s.hostname,
203	      kind,
204	      icon: kind === "Game Server" ? "gamepad" : "server",
205	      tone: kind === "Game Server" ? "v" : "c",
206	      /* A game server's real cpu/ram/disk is its GAME plan's, not the larger,
207	         differently-named base VPS plan it rides on. main fixed this across
208	         the codebase in 6248659; that commit's hunk patched the markup this
209	         rewrite deleted, so it is re-applied here by intent rather than lost
210	         in the merge. `baseDiskGBFor` is the same helper the disk pages use. */
211	      cpu: `${s.gamePlan?.cpuCores ?? s.plan.cpuCores} vCPU`,
212	      ram: `${(s.gamePlan?.ramMB ?? s.plan.ramMB) / 1024} GB`,
213	      disk: `${baseDiskGBFor(s)} GB`,
214	      flag: REGION_COUNTRY[region] ?? "sg",
215	      loc: REGION_LABELS[region] ?? region,
216	      status: nxStatus(s.status),
217	      ...renewal(s.expiresAt),
218	    };
219	  });
220	
221	  const totalServiceCount = servers.length + hostingCount + (hasFree ? 1 : 0);
222	  const stats: Stat[] = [
223	    {
224	      label: "Total Services", value: String(totalServiceCount), icon: "server", tone: "c",
225	      delta: newThisMonth > 0 ? { dir: "up", text: String(newThisMonth) } : undefined,
226	      foot: "Active services",
227	    },
228	    { label: "Monthly Spend", value: money(monthlySpendCents), icon: "card", tone: "", delta: spendDelta, foot: "vs. last month" },
229	    {
230	      label: "Uptime Average", value: formatUptime(uptime), icon: "clock", tone: "v",
231	      foot: uptime.percent === null ? "Not measured yet" : `Last ${uptime.days} day${uptime.days === 1 ? "" : "s"}`,
232	    },
233	    {
234	      label: "Support Tickets", value: String(openTickets), icon: "users2", tone: "m",
235	      foot: openTickets === 1 ? "Open ticket" : "Open tickets",
236	    },
237	  ];
238	
239	  const counts = {
240	    vps: rows.filter((r) => r.kind === "VPS").length,
241	    game: rows.filter((r) => r.kind === "Game Server").length,
242	  };
243	  /* This widget's own table only ever holds VPS/game rows (a "recent
244	     activity" preview, not the full inventory — see the query comment
245	     above) — so its filter tabs stay scoped to what's actually in that
246	     table ("All Services" here means "all rows below", not the account's
247	     grand total) rather than advertising a "Shared Hosting" tab that would
248	     show an accurate count and then filter to nothing. The real total,
249	     across every kind, is the "Total Services" STAT above instead — that's
250	     the number that was actually wrong (silently 3 short, one per missing
251	     hosting account plus the free server), and the full breakdown lives on
252	     /dashboard/services via "View All". */
253	  const filters = [
254	    { label: "All Services", count: rows.length },
255	    { label: "VPS", count: counts.vps },
256	    { label: "Game Servers", count: counts.game },
257	  ];
258	
259	  // SANDBOX-ONLY. Real in production via lib/proxmox.ts `vmStatus` (cpu, mem,
260	  // maxmem, disk, maxdisk per VM); the sandbox has no hypervisor to ask.
261	  // TODO(prod): fetch client-side after paint — one round-trip per server.
262	  const usage: Usage[] = [
263	    { label: "CPU", pct: 42, value: "42%", from: "#3fbcd8", to: "#2f7eef" },
264	    { label: "Memory", pct: 68, value: "68%", from: "#6f37d6", to: "#c026d3" },
265	    { label: "Storage", pct: 37, value: "37%", from: "#d623e1", to: "#6f2ee0" },
266	    { label: "Network", pct: 54, value: "2.4 TB", from: "#14c5e4", to: "#11c88e" },
267	  ];
268	
269	  const activity: Act[] = auditLogs.map((log) => ({
270	    title: log.detail || humanizeAction(log.action),
271	    when: ago(log.createdAt),
272	    ...actIcon(log.action),
273	  }));
274	
275	  const from = (cents: number | undefined, unit = "/mo") =>
276	    cents === undefined ? "—" : money(cents) + unit;
277	  // A real per-customer check, not the general "this product has a promo"
278	  // badge the comment here used to defend — a customer who already redeemed
279	  // it on a prior hosting order kept seeing this on every dashboard visit,
280	  // which reads as a broken promise the moment they actually order and it
281	  // isn't free. Same three-part check the deploy wizard itself gates on
282	  // (app/dashboard/deploy/page.tsx), minus the IP-based cap: this is a
