284	  const hostingPromoEligible =
285	    firstMonthFreeAppliesTo("HOSTING") &&
286	    (await firstMonthFreeEnabled()) &&
287	    (await firstMonthFreeEligible(user.id, null));
288	  const services: Svc[] = [
289	    { key: "vps", name: "VPS Servers", icon: "vps", price: from(plans[0]?.priceCents) },
290	    { key: "game", name: "Game Servers", icon: "game", price: from(gamePlans[0]?.priceCents) },
291	    {
292	      key: "hosting", name: "Cloud Hosting", icon: "hosting", price: from(hostingPlans[0]?.priceCents),
293	      badge: hostingPromoEligible ? "First month free" : undefined,
294	    },
295	    { key: "email", name: "Business Email", icon: "email", price: from(emailPlans[0]?.priceCents) },
296	    // Domains has no fixed plan row — its real price is set per TLD by a live
297	    // registrar quote, so there is no single number here that isn't either
298	    // stale or made up. "$9.99/yr" was a guess presented as a real price;
299	    // this names what's actually true instead.
300	    { key: "domains", name: "Domains", icon: "domains", price: "Priced per TLD" },
301	  ];
302	
303	  // Global Network card (components/nx/DashboardView.tsx) — real regions,
304	  // deduped from the actual Node table, each marked online/degraded from a
305	  // real Proxmox reachability check (lib/monitoring's nodeRamUsage, the same
306	  // read node-capacity alerting uses). No fabricated latency number — see
307	  // NetRegion's own doc comment for why.
308	  const [dbNodes, ramByNode] = await Promise.all([
309	    db.node.findMany({ where: { enabled: true }, select: { name: true, region: true } }),
310	    nodeRamUsage(),
311	  ]);
312	  const reachableByNodeName = new Map(ramByNode.map((r) => [r.node, r.reachable]));
313	  const regionOnline = new Map<string, boolean>();
314	  for (const n of dbNodes) {
315	    const reachable = reachableByNodeName.get(n.name) ?? true; // unreachable ONLY on a confirmed-down read, never assumed
316	    regionOnline.set(n.region, (regionOnline.get(n.region) ?? true) && reachable);
317	  }
318	  const network: NetRegion[] = [...regionOnline.entries()].map(([region, online]) => ({
319	    key: region,
320	    name: customerRegionLabel(region),
321	    lon: REGION_COORDS[region]?.lon ?? 0,
322	    lat: REGION_COORDS[region]?.lat ?? 0,
323	    country: REGION_COUNTRY[region] ?? "",
324	    online,
325	  }));
326	
327	  return (
328	    <>
329	      {transitional && <AutoRefresh />}
330	      <DashboardView
331	        first={user.name.split(" ")[0]}
332	        stats={stats}
333	        rows={rows}
334	        filters={filters}
335	        usage={usage}
336	        activity={activity}
337	        services={services}
338	        network={network}
339	      />
340	    </>
341	  );
342	}
